    R"HTML(<!doctype html><html lang='ru'><head><meta charset='UTF-8'/><meta name='viewport' content='width=device-width, initial-scale=1'/><title>Настройки WiFi модуля</title><style>:root{--bg:#f4f6f8;--panel:#ffffff;--border:#d7dde3;--text:#1f2933;--muted:#7b8794;--accent:#2563eb;--danger:#dc2626;--selected:#e8f1ff;}*{box-sizing:border-box;}body{margin:0;padding:16px;background:var(--bg);color:var(--text);font:15px/1.45 "Segoe UI",Roboto,Arial,sans-serif;}#main{max-width:400px;margin-left:auto;margin-right:auto;}.tabs{margin-bottom:16px;}.tabs>h3{font-size:24px;margin:0 0 16px;text-align:center;font-weight:700;}.tabs>input[type="radio"]{display:none;}.tabs>label{display:inline-block;width:25%;padding:8px 0;border:1px solid var(--border);border-bottom:none;border-radius:6px 6px 0 0;background:var(--bg);color:var(--muted);font-size:13px;font-weight:600;text-align:center;cursor:pointer;user-select:none;transition:color 0.2s,background-color 0.2s;}.tabs>label:hover{color:var(--text);}#tab-btn-1:checked~#tab-label-1,#tab-btn-2:checked~#tab-label-2,#tab-btn-3:checked~#tab-label-3,#tab-btn-4:checked~#tab-label-4{background:var(--panel);color:var(--accent);position:relative;z-index:1;}.tabs>div.tab-panel{display:none;background:var(--panel);border:1px solid var(--border);border-radius:0 8px 8px 8px;padding:12px 14px;margin:0 0 16px;}#tab-btn-1:checked~#content-1,#tab-btn-2:checked~#content-2,#tab-btn-3:checked~#content-3,#tab-btn-4:checked~#content-4{display:block;}.tab-panel h4{font-size:16px;margin:0 0 12px;font-weight:600;}.field{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:12px;}.field label,.field>span{color:var(--muted);font-size:13px;}.field input[type="text"],.field input[type="password"],.field select{padding:7px 9px;border:1px solid var(--border);border-radius:6px;background:#fff;color:var(--text);font:inherit;}.field:has(input[type="text"]),.field:has(select){flex-direction:column;align-items:stretch;gap:4px;}.field:has(input[type="text"]) input,.field:has(select) select{width:100%;}.field:has(input:disabled){opacity:0.5;}input[type="checkbox"]{width:18px;height:18px;accent-color:var(--accent);cursor:pointer;vertical-align:middle;}input[type="checkbox"]:disabled{opacity:0.4;cursor:default;}input[type="text"]:disabled,input[type="password"]:disabled{opacity:0.4;cursor:default;background:#f5f5f5;}.field a{color:var(--accent);text-decoration:none;}.field a:hover{color:var(--accent);background:var(--selected);}.btn{padding:8px 14px;border:1px solid var(--border);border-radius:6px;background:var(--panel);color:var(--text);font:inherit;cursor:pointer;}.btn:hover{border-color:var(--accent);}.btn.primary{background:var(--accent);border-color:var(--accent);color:#fff;}.btn:disabled{opacity:0.5;cursor:default;}.save-row{display:flex;gap:8px;margin-top:4px;}.save-row .btn{min-width:120px;}</style></head><body><div id='main'><div class='tabs'><h3>Настройки WiFi модуля</h3><input type='radio' name='tab-btn' id='tab-btn-1' value='' checked/><label id='tab-label-1' for='tab-btn-1'>Режим STA</label><input type='radio' name='tab-btn' id='tab-btn-2' value=''/><label id='tab-label-2' for='tab-btn-2'>Режим AP</label><input type='radio' name='tab-btn' id='tab-btn-3' value=''/><label id='tab-label-3' for='tab-btn-3'>AP+STA</label><input type='radio' name='tab-btn' id='tab-btn-4' value=''/><label id='tab-label-4' for='tab-btn-4'>Разное</label><div class='tab-panel' id='content-1'><h4>Режим STA (WiFi-клиент)</h4><div class='field'><label for='ssid'>Имя сети (SSID)</label><input type='text' name='ssid' id='ssid' maxlength='32' title='Введите имя сети или выберите сеть из списка доступных сетей' placeholder='SSID сети'/></div><div class='field'><label for='pass'>Пароль</label><input type='text' name='pass' id='pass' maxlength='63' placeholder='пароль сети'/></div><div class='field'><label for='ap_list'>Доступные WiFi сети <a href='#' onclick='getApList()'> (обновить)</a></label><select size='6' onchange="document.getElementById('ssid').value = value" id='ap_list'></select></div><label class='field'><span>Назначить IP вручную</span><input type='checkbox' name='static_ip' id='static_ip'/></label><div id='static_data' style='display: none'><div class='field'><label for='ip'>IP-адрес</label><input type='text' minlength='7' maxlength='15' size='15' id='ip'/></div><div class='field'><label for='mask'>Маска сети</label><input type='text' minlength='7' maxlength='15' size='15' id='mask'/></div><div class='field'><label for='gateway'>Шлюз</label><input type='text' minlength='7' maxlength='15' size='15' id='gateway'/></div><div class='field'><label for='dns1'>DNS1</label><input type='text' minlength='7' maxlength='15' size='15' id='dns1'/></div><div class='field'><label for='dns2'>DNS2</label><input type='text' minlength='7' maxlength='15' size='15' id='dns2'/></div></div></div><div class='tab-panel' id='content-2'><h4>Режим AP (точка доступа)</h4><div class='field'><label for='ap_ssid'>Имя точки доступа (SSID)</label><input type='text' name='ap_ssid' id='ap_ssid' maxlength='32' placeholder='SSID точки доступа'/></div><div class='field'><label for='ap_pass'>Пароль</label><input type='text' name='ap_pass' id='ap_pass' maxlength='63' placeholder='пароль точки доступа'/></div><div class='field'><label for='ap_ip'>IP-адрес</label><input type='text' minlength='7' maxlength='15' size='15' id='ap_ip'/></div><div class='field'><label for='ap_mask'>Маска сети</label><input type='text' minlength='7' maxlength='15' size='15' id='ap_mask'/></div><div class='field'><label for='ap_gateway'>Шлюз</label><input type='text' minlength='7' maxlength='15' size='15' id='ap_gateway'/></div></div><div class='tab-panel' id='content-3'><h4>Комбинированный режим (AP+STA)</h4><label class='field'><span>Включить комбинированный режим</span><input type='checkbox' name='combo' id='combo'/></label></div><div class='tab-panel' id='content-4'><h4>Управление модулем</h4><label class='field'><span>Доступ к настройкам по паролю</span><input type='checkbox' name='use_adm_pass' id='use_adm_pass'/></label><div id='adm_pass' style='display: none'><div class='field'><label for='a_name'>Логин</label><input type='text' name='a_name' id='a_name' maxlength='16' placeholder='логин для входа в настройки'/></div><div class='field'><label for='a_pass'>Пароль</label><input type='text' name='a_pass' id='a_pass' maxlength='63' placeholder='пароль для входа в настройки'/></div></div><label class='field' id='led_on_lab'><span>Использовать индикаторный светодиод</span><input type='checkbox' name='led_on' id='led_on'/></label></div><div class='save-row'><button class='btn' onclick="window.open('/', '_self', false)"> Назад </button><button id='btn_save' class='btn primary' onclick='sendData()' disabled> Сохранить </button></div></div></div><script>const DATA_URL="/wifi_getconfig";function checkSsidValue(i_id,is_empty){var tag=document.getElementById(i_id);if(is_empty&&tag.value.length==0){return true;};var res=i_id=="a_name"?tag.value.length>=5&&tag.value.length<=16:tag.value.length>0&&tag.value.length<=32;if(!res){tag.focus();showErrorPage(i_id);if(i_id=="a_name"){alert("Длина имени должна быть не менее 5 и не более 16 символов! \n\n Разрешенные символы:0..9, A..Z, a..z, - , _",);}else{alert("Длина SSID должна быть не менее 1 и не более 32 символов! \n\n Разрешенные символы:0..9, A..Z, a..z, - , _",);}};return res;};function checkPassValue(i_id,is_empty){var tag=document.getElementById(i_id);if(is_empty&&tag.value.length==0){return true;};var res=tag.value.length>=8&&tag.value.length<=63;if(!res){tag.focus();showErrorPage(i_id);alert("Длина пароля должна быть не менее 8 и не более 63 символов! \n\n Не разрешаются символы кириллицы и пробелы",);};return res;};function ipAddressCheck(i_id){var tag=document.getElementById(i_id);var regEx=/^(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$/;if(tag.value.match(regEx)){return true;}else{tag.focus();showErrorPage(i_id);alert("Неправильно введен IP адрес!\n\n IP адрес должен иметь вид XXX.XXX.XXX.XXX \n\n где XXX - число в интервале 0..255",);return false;}};function validate_form(){var res=checkSsidValue("ap_ssid",false)&&checkPassValue("ap_pass",true)&&ipAddressCheck("ap_ip")&&ipAddressCheck("ap_mask")&&ipAddressCheck("ap_gateway");if(res){res=checkSsidValue("ssid",true)&&checkPassValue("pass",true);};if(res&&document.getElementById("static_ip").checked){res=ipAddressCheck("ip")&&ipAddressCheck("gateway")&&ipAddressCheck("mask");};if(res&&document.getElementById("use_adm_pass").checked){res=checkSsidValue("a_name",false)&&checkPassValue("a_pass",false);};return res;};function showErrorPage(id){if(id=="ssid"||id=="pass"||id=="ip"||id=="gateway"||id=="mask"){document.getElementById("tab-btn-1").checked=true;}else if(id=="ap_ssid"||id=="ap_pass"||id=="ap_ip"||id=="ap_gateway"||id=="ap_mask"){document.getElementById("tab-btn-2").checked=true;}else{document.getElementById("tab-btn-4").checked=true;};document.getElementById(id).focus();};function enableBtnSave(){document.getElementById("btn_save").removeAttribute("disabled");};function showStaticData(){showDiv("static_ip","static_data",true);};function showAdmPassData(){showDiv("use_adm_pass","adm_pass",true);};function showDiv(id1,id2,btnEnbl){var x=document.getElementById(id1).checked?"block":"none";document.getElementById(id2).style.display=x;if(btnEnbl){enableBtnSave();}};function sendData(){if(validate_form()){document.getElementById("btn_save").disabled="disabled";let form_data={ap_ssid:document.getElementById("ap_ssid").value,ap_pass:document.getElementById("ap_pass").value,ap_ip:document.getElementById("ap_ip").value,ap_gateway:document.getElementById("ap_gateway").value,ap_mask:document.getElementById("ap_mask").value,ssid:document.getElementById("ssid").value,pass:document.getElementById("pass").value,static_ip:document.getElementById("static_ip").checked,ip:document.getElementById("ip").value,gateway:document.getElementById("gateway").value,mask:document.getElementById("mask").value,dns1:document.getElementById("dns1").value,dns2:document.getElementById("dns2").value,ap_sta:document.getElementById("combo").checked,use_adm_pass:document.getElementById("use_adm_pass").checked,a_name:document.getElementById("a_name").value,a_pass:document.getElementById("a_pass").value,led_on:document.getElementById("led_on").checked,};var xhr=new XMLHttpRequest();xhr.open("POST","/wifi_setconfig",true);xhr.setRequestHeader("Content-Type","text/json");xhr.onreadystatechange=function(){if(this.readyState!=4)return;if(this.status==401||this.status==403){document.body.innerHTML="<h4>Отказано в доступе.<br><a href='"+location.pathname+"'>Войти снова</a></h4>";return;};document.body.innerHTML=this.responseText;};xhr.onerror=function(){alert("Нет связи с модулем, попробуйте ещё раз");document.getElementById("btn_save").removeAttribute("disabled");};xhr.send(JSON.stringify(form_data));}};var authErrorShown=false;function showAuthError(){if(authErrorShown)return;authErrorShown=true;alert("Отказано в доступе. Страница настроек требует авторизации.");window.location.href=location.pathname;};function getApList(){var sel=document.getElementById("ap_list");sel.disabled=true;while(sel.options.length>0){sel.remove(0);};var request=new XMLHttpRequest();request.open("GET","/wifi_getaplist",true);request.onload=function(){if(request.readyState==4&&(request.status==401||request.status==403)){showAuthError();return;};if(request.readyState==4&&request.status==200){var config_str=request.responseText;var doc=JSON.parse(config_str);if(doc.aps.length>0){sel.disabled=false;for(var i=0;i<doc.aps.length;i++){var opt=new Option(doc.aps[i],doc.aps[i]);sel.options[i]=opt;if(sel.options[i].value.toUpperCase()===document.getElementById("ssid").value.toUpperCase()){sel.options[i].selected=true;}}}}};request.send();};function getConfig(){var request=new XMLHttpRequest();request.open("GET",DATA_URL,true);request.onload=function(){if(request.readyState==4&&(request.status==401||request.status==403)){showAuthError();return;};if(request.readyState==4&&request.status==200){var config_str=request.responseText;var doc=JSON.parse(config_str);document.getElementById("ap_ssid").setAttribute("value",doc.ap_ssid);document.getElementById("ap_pass").setAttribute("value",doc.ap_pass);document.getElementById("ap_ip").setAttribute("value",doc.ap_ip);document.getElementById("ap_gateway").setAttribute("value",doc.ap_gateway);document.getElementById("ap_mask").setAttribute("value",doc.ap_mask);document.getElementById("ssid").setAttribute("value",doc.ssid);document.getElementById("pass").setAttribute("value",doc.pass);document.getElementById("static_ip").checked=doc.static_ip==1;showDiv("static_ip","static_data",false);document.getElementById("ip").setAttribute("value",doc.ip);document.getElementById("gateway").setAttribute("value",doc.gateway);document.getElementById("mask").setAttribute("value",doc.mask);document.getElementById("dns1").setAttribute("value",doc.dns1);document.getElementById("dns2").setAttribute("value",doc.dns2);if(doc.use_combo!=1){document.getElementById("tab-label-3").style.display="none";};document.getElementById("combo").checked=doc.ap_sta==1;document.getElementById("use_adm_pass").checked=doc.use_adm_pass==1;showDiv("use_adm_pass","adm_pass",false);document.getElementById("a_name").setAttribute("value",doc.a_name);document.getElementById("a_pass").setAttribute("value",doc.a_pass);if(doc.use_led!=1){document.getElementById("led_on_lab").style.display="none";}else{document.getElementById("led_on").checked=doc.led_on==1;}}};request.send();getApList();};function keyUpBySsid(){this.value=this.value.replace(/[^a-zA-Z0-9_/-]/g,"");};function keyUpByPass(){this.value=this.value.replace(/[А-Яа-яёЁ/ ]/g,"");};function keyUpByIP(){this.value=this.value.replace(/[^0-9.]/g,"");};function setApIpData(){setGateway("ap_gateway","ap_ip",false);setMask("ap_mask");};function setStaIpData(){setGateway("gateway","ip",true);setMask("mask");};function setMask(i_id){if(document.getElementById(i_id).value.length==0){document.getElementById(i_id).setAttribute("value","255.255.255.0");}};function setGateway(i_id,o_id,sub){if(document.getElementById(i_id).value.length==0){var s=document.getElementById(o_id).value;if(sub){s=s.substr(0,s.lastIndexOf(".")+1)+"1";};document.getElementById(i_id).setAttribute("value",s);}};document.getElementById("ap_ssid").addEventListener("keyup",keyUpBySsid);document.getElementById("ssid").addEventListener("keyup",keyUpBySsid);document.getElementById("ap_pass").addEventListener("keyup",keyUpByPass);document.getElementById("pass").addEventListener("keyup",keyUpByPass);document.getElementById("ip").addEventListener("keyup",keyUpByIP);document.getElementById("gateway").addEventListener("keyup",keyUpByIP);document.getElementById("mask").addEventListener("keyup",keyUpByIP);document.getElementById("dns1").addEventListener("keyup",keyUpByIP);document.getElementById("dns2").addEventListener("keyup",keyUpByIP);document.getElementById("ap_ip").addEventListener("keyup",keyUpByIP);document.getElementById("ap_gateway").addEventListener("keyup",keyUpByIP);document.getElementById("ap_mask").addEventListener("keyup",keyUpByIP);document.getElementById("a_name").addEventListener("keyup",keyUpBySsid);document.getElementById("a_pass").addEventListener("keyup",keyUpByPass);document.getElementById("ap_ssid").addEventListener("input",enableBtnSave);document.getElementById("ap_pass").addEventListener("input",enableBtnSave);document.getElementById("ap_ip").addEventListener("input",enableBtnSave);document.getElementById("ap_ip").addEventListener("blur",setApIpData);document.getElementById("ap_gateway").addEventListener("input",enableBtnSave);document.getElementById("ap_gateway").addEventListener("focus",setApIpData);document.getElementById("ap_mask").addEventListener("input",enableBtnSave);document.getElementById("ap_mask").addEventListener("focus",setApIpData);document.getElementById("ssid").addEventListener("input",enableBtnSave);document.getElementById("pass").addEventListener("input",enableBtnSave);document.getElementById("ap_list").addEventListener("change",enableBtnSave);document.getElementById("static_ip").addEventListener("input",showStaticData);document.getElementById("ip").addEventListener("input",enableBtnSave);document.getElementById("ip").addEventListener("blur",setStaIpData);document.getElementById("gateway").addEventListener("input",enableBtnSave);document.getElementById("gateway").addEventListener("focus",setStaIpData);document.getElementById("mask").addEventListener("input",enableBtnSave);document.getElementById("mask").addEventListener("focus",setStaIpData);document.getElementById("dns1").addEventListener("input",enableBtnSave);document.getElementById("dns1").addEventListener("focus",setStaIpData);document.getElementById("dns2").addEventListener("input",enableBtnSave);document.getElementById("dns2").addEventListener("focus",setStaIpData);document.getElementById("combo").addEventListener("input",enableBtnSave);document.getElementById("use_adm_pass").addEventListener("input",showAdmPassData);document.getElementById("a_name").addEventListener("input",enableBtnSave);document.getElementById("a_pass").addEventListener("input",enableBtnSave);document.getElementById("led_on").addEventListener("input",enableBtnSave);document.addEventListener("DOMContentLoaded",getConfig);</script></body></html>)HTML";
